package cli

import (
	"fmt"
	"io"
	"os"
	"path/filepath"

	skills "github.com/jdbencardinop/tesseraworkspaces/assets/skills"
	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func addCmd() *cobra.Command {
	var templates []string
	var newBranch string
	var base string
	var open bool
	var force bool
	var useTmux bool

	cmd := &cobra.Command{
		Use:   "add <feature>",
		Short: "Create a feature workspace",
		Long: `Create a feature workspace with an inject/ directory for shared files.

Files in inject/ are symlinked into every worktree. Use -n to also
create a first worktree branch, and --open to launch the agent.

Note: injected files appear as untracked in git status. Add them to
.gitignore or place them in an already-ignored subfolder.`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]
			root := internal.FeaturePath(feature)

			wsRoot := internal.TwsRoot()
			internal.Must(os.MkdirAll(filepath.Join(wsRoot, ".tws-workspace"), 0755))
			internal.Must(os.MkdirAll(filepath.Join(root, "worktrees"), 0755))
			internal.Must(os.WriteFile(filepath.Join(root, "FEATURE.md"), []byte("# "+feature+"\n"), 0644))

			// Create inject/ dir
			injectDir := internal.InjectPath(root)
			internal.Must(os.MkdirAll(injectDir, 0755))

			// Apply templates
			applyTemplates(injectDir, templates)

			// Add default CLAUDE.local.md if not provided by any template
			claudeLocal := filepath.Join(injectDir, "CLAUDE.local.md")
			if _, err := os.Stat(claudeLocal); os.IsNotExist(err) {
				internal.Must(os.WriteFile(claudeLocal, []byte("# "+feature+" - shared context\n\nThis file is symlinked into every worktree for this feature.\nEdit it in the workspace inject/ directory.\n"), 0644))
			}

			// Install orchestrator skill in the feature dir
			orchPath := filepath.Join(root, ".claude", "skills", "tesseraworkspaces-orchestrator", "SKILL.md")
			installFile(orchPath, skills.ClaudeOrchestratorSkill, false)

			fmt.Println("Feature added:", feature)

			// Quick start: create worktree if -n specified
			if newBranch != "" {
				if err := createWorktree(feature, newBranch, base, "", force); err != nil {
					return err
				}

				if open {
					path := internal.WorktreePath(feature, newBranch)
					if useTmux {
						openWithTmux(feature, newBranch, path)
					} else {
						openDirect(path)
					}
				}
			}
			return nil
		},
	}

	cmd.Flags().StringArrayVar(&templates, "template", nil, "Template directory to copy into inject/ (can be specified multiple times)")
	cmd.Flags().StringVarP(&newBranch, "new", "n", "", "Also create a worktree branch")
	cmd.Flags().StringVar(&base, "base", "", "Base branch for the new worktree (default: repo's default branch)")
	cmd.Flags().BoolVar(&open, "open", false, "Open the worktree after creation (used with -n)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")
	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Open in tmux session (used with --open)")

	return cmd
}

// applyTemplates copies files from the configured template dir and any
// explicit --template dirs into the inject directory.
func applyTemplates(injectDir string, extraTemplates []string) {
	// Configured default template first
	defaultTemplate := internal.TemplatePath()
	if defaultTemplate != "" {
		count, err := copyDir(defaultTemplate, injectDir)
		if err != nil {
			fmt.Printf("Warning: default template copy failed: %v\n", err)
		} else if count > 0 {
			fmt.Printf("Copied %d file(s) from default template\n", count)
		}
	}

	// Then explicit --template dirs (layered in order)
	for _, tmplDir := range extraTemplates {
		info, err := os.Stat(tmplDir)
		if err != nil || !info.IsDir() {
			fmt.Printf("Warning: template directory not found: %s\n", tmplDir)
			continue
		}
		count, err := copyDir(tmplDir, injectDir)
		if err != nil {
			fmt.Printf("Warning: template copy failed for %s: %v\n", tmplDir, err)
		} else if count > 0 {
			fmt.Printf("Copied %d file(s) from %s\n", count, tmplDir)
		}
	}
}

// copyDir copies all files from src to dst, preserving directory structure.
// Does not overwrite existing files. Returns the count of files copied.
func copyDir(src, dst string) (int, error) {
	count := 0
	err := filepath.Walk(src, func(srcPath string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		relPath, err := filepath.Rel(src, srcPath)
		if err != nil {
			return err
		}
		if relPath == "." {
			return nil
		}

		dstPath := filepath.Join(dst, relPath)

		if info.IsDir() {
			return os.MkdirAll(dstPath, 0755)
		}

		// Skip if exists (conflict resolution is a separate feature)
		if _, err := os.Stat(dstPath); err == nil {
			fmt.Printf("  skip: %s (exists)\n", relPath)
			return nil
		}

		// Copy file
		in, err := os.Open(srcPath)
		if err != nil {
			return err
		}
		defer in.Close() //nolint:errcheck

		out, err := os.Create(dstPath)
		if err != nil {
			return err
		}
		defer out.Close() //nolint:errcheck

		if _, err := io.Copy(out, in); err != nil {
			return err
		}
		count++
		return nil
	})
	return count, err
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func newCmd() *cobra.Command {
	var base string
	var force bool
	var repo string

	cmd := &cobra.Command{
		Use:   "new <feature> <branch>",
		Short: "Create a worktree branch",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			return createWorktree(args[0], args[1], base, repo, force)
		},
	}

	cmd.Flags().StringVar(&base, "base", "", "Parent branch, tag, or commit (default: selected repo's origin/HEAD)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")
	cmd.Flags().StringVar(&repo, "repo", "", "Source repository path (for cross-repo worktrees)")

	return cmd
}

// createWorktree is the shared logic for creating a worktree branch.
// Used by both tws new and tws add -n. Explicit base refs are literal;
// an omitted base resolves from the selected repository's origin/HEAD.
func createWorktree(feature, name, requestedBase, repoPath string, force bool) error {
	featurePath := internal.FeaturePath(feature)
	path := internal.WorktreePath(feature, name)

	if err := os.MkdirAll(featurePath, 0755); err != nil {
		return err
	}

	stack, _ := internal.LoadStack(featurePath)
	repoRoot, storedRepo, err := resolveSourceRepo(featurePath, stack, repoPath)
	if err != nil {
		return err
	}

	baseName, baseRef, err := resolveCreationBase(repoRoot, storedRepo, stack, requestedBase)
	if err != nil {
		return err
	}

	cfg := internal.LoadConfig()
	gitBranch := name
	if cfg.BranchPrefix != "" {
		gitBranch = cfg.BranchPrefix + name
	}

	branchExists := internal.VerifyGitRef(repoRoot, gitBranch) == nil
	if !branchExists && gitBranch != name && internal.VerifyGitRef(repoRoot, name) == nil {
		gitBranch = name
		branchExists = true
	}

	if branchExists {
		if isCheckedOutIn(repoRoot, gitBranch) && !force {
			return fmt.Errorf("branch %q is already checked out in another worktree; use --force to check it out anyway", gitBranch)
		}

		gitArgs := []string{"worktree", "add"}
		if force {
			gitArgs = append(gitArgs, "--force")
		}
		gitArgs = append(gitArgs, path, gitBranch)
		if err := internal.RunDir(repoRoot, "git", gitArgs...); err != nil {
			return err
		}
	} else {
		if err := internal.RunDir(repoRoot, "git", "worktree", "add", path, "-b", gitBranch, baseRef); err != nil {
			return err
		}
	}

	if !internal.HasBranch(stack, name) {
		entry := internal.StackEntry{
			Name: name,
			Base: baseName,
			Repo: storedRepo,
		}
		if gitBranch != name {
			entry.Branch = gitBranch
		}
		stack.Branches = append(stack.Branches, entry)
		if err := internal.SaveStack(featurePath, stack); err != nil {
			return err
		}
	}

	target := internal.ResolveInjectInto("")
	if err := internal.InjectFiles(featurePath, path, target); err != nil {
		fmt.Printf("Warning: inject failed: %v\n", err)
	}

	if cfg.AutoHooks != nil && *cfg.AutoHooks {
		if err := installHooksForWorktree(path, feature); err != nil {
			fmt.Printf("Warning: auto-hooks install failed: %v\n", err)
		}
	}

	if storedRepo != "" {
		fmt.Printf("Worktree created: %s (base: %s, repo: %s)\n", path, baseName, storedRepo)
	} else {
		fmt.Printf("Worktree created: %s (base: %s)\n", path, baseName)
	}
	return nil
}

func resolveSourceRepo(featurePath string, stack internal.Stack, requestedRepo string) (string, string, error) {
	if requestedRepo != "" {
		absRepo, err := internal.AbsPath(requestedRepo)
		if err != nil {
			return "", "", fmt.Errorf("invalid repo path %s: %w", requestedRepo, err)
		}
		repoRoot, err := internal.GitRepoRootIn(absRepo)
		if err != nil {
			return "", "", fmt.Errorf("%s is not a Git repository", requestedRepo)
		}
		return repoRoot, repoRoot, nil
	}

	if repoRoot, err := internal.MainRepoRoot(); err == nil {
		return repoRoot, "", nil
	}

	type candidate struct {
		root       string
		storedRepo string
	}
	candidates := make(map[string]candidate)
	for _, entry := range stack.Branches {
		if entry.Repo != "" {
			root, err := internal.GitRepoRootIn(entry.Repo)
			if err == nil {
				candidates[root] = candidate{root: root, storedRepo: root}
			}
			continue
		}

		worktreePath := filepath.Join(featurePath, "worktrees", entry.Name)
		if _, err := os.Stat(worktreePath); err != nil {
			continue
		}
		root, err := internal.MainRepoRootIn(worktreePath)
		if err == nil {
			candidates[root] = candidate{root: root}
		}
	}

	if len(candidates) == 1 {
		for _, c := range candidates {
			return c.root, c.storedRepo, nil
		}
	}
	if len(candidates) > 1 {
		return "", "", fmt.Errorf("feature uses multiple repositories; specify --repo")
	}
	return "", "", fmt.Errorf("could not infer source repository; run from a Git repo or specify --repo")
}

func resolveCreationBase(repoRoot, storedRepo string, stack internal.Stack, requestedBase string) (string, string, error) {
	if requestedBase == "" {
		baseName, err := internal.DefaultBranchIn(repoRoot)
		if err != nil {
			return "", "", err
		}
		remoteRef := "origin/" + baseName
		if internal.VerifyGitRef(repoRoot, remoteRef) == nil {
			return baseName, remoteRef, nil
		}
		if internal.VerifyGitRef(repoRoot, baseName) == nil {
			return baseName, baseName, nil
		}
		return "", "", fmt.Errorf("default branch %q does not exist in %s", baseName, repoRoot)
	}

	baseRef := requestedBase
	if parent := internal.GetBranch(stack, requestedBase); parent.Name != "" {
		if !sameStackRepo(parent.Repo, storedRepo) {
			return "", "", fmt.Errorf("base %q belongs to a different repository", requestedBase)
		}
		baseRef = parent.GitBranch()
	}
	if err := internal.VerifyGitRef(repoRoot, baseRef); err != nil {
		return "", "", fmt.Errorf("base ref %q does not exist in %s", requestedBase, repoRoot)
	}
	return requestedBase, baseRef, nil
}

func sameStackRepo(a, b string) bool {
	if a == "" && b == "" {
		return true
	}
	return a == b
}

func isCheckedOutIn(repoRoot, branch string) bool {
	out, err := exec.Command("git", "-C", repoRoot, "worktree", "list", "--porcelain").Output()
	if err != nil {
		return false
	}
	for line := range strings.SplitSeq(string(out), "\n") {
		if strings.TrimSpace(line) == "branch refs/heads/"+branch {
			return true
		}
	}
	return false
}

package cli

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

func TestCreateWorktreeFromExplicitLocalBase(t *testing.T) {
	repo := setupGitRepo(t, "master")
	masterSHA := gitOutput(t, repo, "rev-parse", "master")

	gitRun(t, repo, "switch", "-c", "dirty-head")
	writeAndCommit(t, repo, "dirty.txt", "dirty\n", "dirty head")
	if got := gitOutput(t, repo, "rev-parse", "HEAD"); got == masterSHA {
		t.Fatal("test setup did not move HEAD away from master")
	}

	withWorkspaceEnv(t, repo)
	if err := createWorktree("feature", "local-base", "master", repo, false); err != nil {
		t.Fatalf("createWorktree: %v", err)
	}

	assertWorktreeHEAD(t, "feature", "local-base", masterSHA)
	stack, err := internal.LoadStack(internal.FeaturePath("feature"))
	if err != nil {
		t.Fatal(err)
	}
	if got := internal.GetBranch(stack, "local-base").Base; got != "master" {
		t.Fatalf("base = %q, want master", got)
	}
}

func TestCreateWorktreeFromExplicitRemoteTagAndSHA(t *testing.T) {
	repo := setupGitRepo(t, "master")
	masterSHA := gitOutput(t, repo, "rev-parse", "master")
	gitRun(t, repo, "tag", "base-tag", masterSHA)
	withWorkspaceEnv(t, repo)

	cases := []struct {
		name string
		base string
	}{
		{name: "remote-base", base: "origin/master"},
		{name: "tag-base", base: "base-tag"},
		{name: "sha-base", base: masterSHA},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if err := createWorktree("feature", tc.name, tc.base, repo, false); err != nil {
				t.Fatalf("createWorktree: %v", err)
			}
			assertWorktreeHEAD(t, "feature", tc.name, masterSHA)
		})
	}
}

func TestCreateWorktreeDefaultUsesSelectedRepoOriginHEAD(t *testing.T) {
	repo := setupGitRepo(t, "master")
	masterSHA := gitOutput(t, repo, "rev-parse", "master")
	gitRun(t, repo, "switch", "-c", "other")
	writeAndCommit(t, repo, "other.txt", "other\n", "other")
	withWorkspaceEnv(t, repo)

	if err := createWorktree("feature", "default-base", "", repo, false); err != nil {
		t.Fatalf("createWorktree: %v", err)
	}
	assertWorktreeHEAD(t, "feature", "default-base", masterSHA)

	stack, _ := internal.LoadStack(internal.FeaturePath("feature"))
	if got := internal.GetBranch(stack, "default-base").Base; got != "master" {
		t.Fatalf("base = %q, want master", got)
	}
}

func TestCreateWorktreeInvalidBaseDoesNotWriteMetadata(t *testing.T) {
	repo := setupGitRepo(t, "master")
	withWorkspaceEnv(t, repo)

	err := createWorktree("feature", "bad-base", "does-not-exist", repo, false)
	if err == nil {
		t.Fatal("expected invalid base error")
	}
	if _, statErr := os.Stat(internal.WorktreePath("feature", "bad-base")); !os.IsNotExist(statErr) {
		t.Fatalf("worktree unexpectedly exists: %v", statErr)
	}
	if stack, loadErr := internal.LoadStack(internal.FeaturePath("feature")); loadErr == nil && internal.HasBranch(stack, "bad-base") {
		t.Fatal("invalid branch was written to stack")
	}
}

func TestCreateWorktreeInfersRepoFromFeatureDirectory(t *testing.T) {
	repo := setupGitRepo(t, "master")
	withWorkspaceEnv(t, repo)

	if err := createWorktree("feature", "first", "master", repo, false); err != nil {
		t.Fatalf("first worktree: %v", err)
	}
	featurePath := internal.FeaturePath("feature")
	oldCWD, _ := os.Getwd()
	t.Cleanup(func() { _ = os.Chdir(oldCWD) })
	if err := os.Chdir(featurePath); err != nil {
		t.Fatal(err)
	}

	if err := createWorktree("feature", "second", "master", "", false); err != nil {
		t.Fatalf("feature-dir createWorktree: %v", err)
	}
	assertWorktreeHEAD(t, "feature", "second", gitOutput(t, repo, "rev-parse", "master"))
}

func TestResolveSourceRepoRejectsAmbiguousFeature(t *testing.T) {
	repoA := setupGitRepo(t, "master")
	repoB := setupGitRepo(t, "main")
	featurePath := t.TempDir()
	stack := internal.Stack{Branches: []internal.StackEntry{
		{Name: "a", Base: "master", Repo: repoA},
		{Name: "b", Base: "main", Repo: repoB},
	}}

	oldCWD, _ := os.Getwd()
	t.Cleanup(func() { _ = os.Chdir(oldCWD) })
	if err := os.Chdir(featurePath); err != nil {
		t.Fatal(err)
	}
	if _, _, err := resolveSourceRepo(featurePath, stack, ""); err == nil || !strings.Contains(err.Error(), "multiple repositories") {
		t.Fatalf("expected ambiguity error, got %v", err)
	}
}

func setupGitRepo(t *testing.T, defaultBranch string) string {
	t.Helper()
	root := t.TempDir()
	repo := filepath.Join(root, "repo")
	remote := filepath.Join(root, "remote.git")
	gitRun(t, "", "init", "--bare", remote)
	gitRun(t, "", "init", "-b", defaultBranch, repo)
	gitRun(t, repo, "config", "user.name", "TWS Test")
	gitRun(t, repo, "config", "user.email", "tws@example.test")
	writeAndCommit(t, repo, "README.md", "base\n", "initial")
	gitRun(t, repo, "remote", "add", "origin", remote)
	gitRun(t, repo, "push", "-u", "origin", defaultBranch)
	gitRun(t, remote, "symbolic-ref", "HEAD", "refs/heads/"+defaultBranch)
	gitRun(t, repo, "remote", "set-head", "origin", "-a")
	return repo
}

func withWorkspaceEnv(t *testing.T, repo string) {
	t.Helper()
	t.Setenv("HOME", t.TempDir())
	t.Setenv("TWS_ROOT", filepath.Join(t.TempDir(), "workspace"))
	oldCWD, _ := os.Getwd()
	t.Cleanup(func() { _ = os.Chdir(oldCWD) })
	if err := os.Chdir(repo); err != nil {
		t.Fatal(err)
	}
}

func assertWorktreeHEAD(t *testing.T, feature, name, want string) {
	t.Helper()
	got := gitOutput(t, internal.WorktreePath(feature, name), "rev-parse", "HEAD")
	if got != want {
		t.Fatalf("worktree HEAD = %s, want %s", got, want)
	}
}

func writeAndCommit(t *testing.T, repo, name, content, message string) {
	t.Helper()
	if err := os.WriteFile(filepath.Join(repo, name), []byte(content), 0644); err != nil {
		t.Fatal(err)
	}
	gitRun(t, repo, "add", name)
	gitRun(t, repo, "commit", "-m", message)
}

func gitRun(t *testing.T, dir string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", args...)
	if dir != "" {
		cmd.Dir = dir
	}
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git %v: %v\n%s", args, err, out)
	}
}

func gitOutput(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %v: %v\n%s", args, err, out)
	}
	return strings.TrimSpace(string(out))
}

package internal

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func RequireTool(name string) {
	if _, err := exec.LookPath(name); err != nil {
		fmt.Printf("Error: required tool %q not found in PATH\n", name)
		os.Exit(1)
	}
}

func MainRepoRoot() (string, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", err
	}
	return MainRepoRootIn(cwd)
}

// MainRepoRootIn returns the primary repository root for a repo or linked worktree.
func MainRepoRootIn(path string) (string, error) {
	out, err := exec.Command("git", "-C", path, "rev-parse", "--git-common-dir").Output()
	if err != nil {
		return "", err
	}
	gitDir := strings.TrimSpace(string(out))
	if !filepath.IsAbs(gitDir) {
		gitDir = filepath.Join(path, gitDir)
	}
	gitDir = filepath.Clean(gitDir)

	if filepath.Base(gitDir) == ".git" {
		return filepath.Dir(gitDir), nil
	}
	return filepath.Dir(gitDir), nil
}

func RepoRoot() (string, error) {
	out, err := exec.Command("git", "rev-parse", "--show-toplevel").Output()
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(out)), nil
}

func BranchExists(branch string) bool {
	err := exec.Command("git", "rev-parse", "--verify", branch).Run()
	return err == nil
}

// DefaultBranch returns the current repository's default branch name.
// Deprecated for repo-aware flows; prefer DefaultBranchIn.
func DefaultBranch() string {
	branch, err := DefaultBranchIn("")
	if err != nil {
		return "main"
	}
	return branch
}

// DefaultBranchIn returns the selected repository's default branch name.
// It prefers origin/HEAD, then the repository's initial branch, and finally main.
func DefaultBranchIn(repoPath string) (string, error) {
	args := []string{"rev-parse", "--abbrev-ref", "origin/HEAD"}
	if repoPath != "" {
		args = append([]string{"-C", repoPath}, args...)
	}
	if out, err := exec.Command("git", args...).Output(); err == nil {
		branch := strings.TrimSpace(string(out))
		return strings.TrimPrefix(branch, "origin/"), nil
	}

	args = []string{"symbolic-ref", "--short", "HEAD"}
	if repoPath != "" {
		args = append([]string{"-C", repoPath}, args...)
	}
	if out, err := exec.Command("git", args...).Output(); err == nil {
		return strings.TrimSpace(string(out)), nil
	}

	return "main", nil
}

// VerifyGitRef checks that ref resolves to a commit in the selected repository.
func VerifyGitRef(repoPath, ref string) error {
	args := []string{"rev-parse", "--verify", ref + "^{commit}"}
	if repoPath != "" {
		args = append([]string{"-C", repoPath}, args...)
	}
	return exec.Command("git", args...).Run()
}

// GitRepoRootIn validates repoPath and returns its top-level directory.
func GitRepoRootIn(repoPath string) (string, error) {
	args := []string{"rev-parse", "--show-toplevel"}
	if repoPath != "" {
		args = append([]string{"-C", repoPath}, args...)
	}
	out, err := exec.Command("git", args...).Output()
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(out)), nil
}

// AbsPath returns the absolute path, resolving relative paths.
func AbsPath(path string) (string, error) {
	return filepath.Abs(path)
}

func Run(name string, args ...string) error {
	cmd := exec.Command(name, args...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin

	return cmd.Run()
}

func RunDir(dir string, name string, args ...string) error {
	cmd := exec.Command(name, args...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin
	cmd.Dir = dir

	return cmd.Run()
}

// RunDirClean runs a command in a directory, filtering git hint/warning noise
// from stderr. Actual errors are still shown.
func RunDirClean(dir string, name string, args ...string) error {
	return runWithFilteredStderr(dir, name, args...)
}

func runWithFilteredStderr(dir, name string, args ...string) error {
	cmd := exec.Command(name, args...)
	cmd.Stdout = os.Stdout
	cmd.Dir = dir

	stderr, err := cmd.StderrPipe()
	if err != nil {
		return err
	}

	if err := cmd.Start(); err != nil {
		return err
	}

	// Read stderr and filter
	buf := make([]byte, 4096)
	for {
		n, readErr := stderr.Read(buf)
		if n > 0 {
			lines := strings.Split(string(buf[:n]), "\n")
			for _, line := range lines {
				trimmed := strings.TrimSpace(line)
				if trimmed == "" {
					continue
				}
				// Filter git hint and advice lines
				if strings.HasPrefix(trimmed, "hint:") ||
					strings.HasPrefix(trimmed, "Disable this message") {
					continue
				}
				// Reformat cherry-pick skip warnings
				if strings.Contains(trimmed, "skipped previously applied commit") {
					fmt.Fprintf(os.Stderr, "    (skipped duplicate commit)\n")
					continue
				}
				fmt.Fprintln(os.Stderr, line)
			}
		}
		if readErr != nil {
			break
		}
	}

	return cmd.Wait()
}

func RunSilent(name string, args ...string) error {
	cmd := exec.Command(name, args...)
	return cmd.Run()
}

func RunSilentDir(dir string, name string, args ...string) error {
	cmd := exec.Command(name, args...)
	cmd.Dir = dir
	return cmd.Run()
}

// IsPrunableWorktree checks if a branch has a stale (prunable) worktree entry,
// meaning the directory was deleted but git still tracks it.
func IsPrunableWorktree(branch string) bool {
	out, err := exec.Command("git", "worktree", "list", "--porcelain").Output()
	if err != nil {
		return false
	}
	lines := strings.Split(string(out), "\n")
	for i, line := range lines {
		if strings.TrimSpace(line) == "branch refs/heads/"+branch {
			// Check surrounding lines in the same worktree block for "prunable"
			for j := i - 3; j <= i+2 && j < len(lines); j++ {
				if j < 0 {
					continue
				}
				if strings.HasPrefix(lines[j], "prunable") {
					return true
				}
			}
		}
	}
	return false
}

func Must(err error) {
	if err != nil {
		fmt.Println("Error:", err)
		os.Exit(1)
	}
}
